window.RP_SESSION={"id":"S-2c34fb97b793","messages":[{"id":"RP-II-0111852","time":"2026-06-23T17:25:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"...","characters":["P-44a1082366bf"]},{"id":"RP-II-0111853","time":"2026-06-23T17:25:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"..","characters":["P-44a1082366bf"]},{"id":"RP-II-0111854","time":"2026-06-23T17:25:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":".","characters":["P-44a1082366bf"]},{"id":"RP-II-0111855","time":"2026-06-23T17:27:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"션에게 라쿤의 건초로 향한다는 언질을 받고 얼마 지나지 않은 시점","characters":["P-44a1082366bf"]},{"id":"RP-II-0111856","time":"2026-06-23T17:27:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"파우스트는 도서관에 앉아 조용히 편지를 쓰고있었다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111857","time":"2026-06-23T17:28:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"고급스러운 재질의 만년필이 검푸른 잉크를 머금고, 새하얀 편지지 위를 정처없이 맴돌다 흐드러지길 몇번","characters":["P-44a1082366bf"]},{"id":"RP-II-0111858","time":"2026-06-23T17:29:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"파우스트는 이 낱장 위에 옮겨적을 말도, 마음도 무엇 하나 제대로 다듬지 못하고 망설이고 있었다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111859","time":"2026-06-23T17:30:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"그녀는 의사였다. 로얄가드에 머물 적, 훈련과 전쟁으로 몸 성할 날 없는 이들을 위해 붕대를 감고 살을 꾀매며 연고를 만들었다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111860","time":"2026-06-23T17:31:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"그녀는 사람이었기에 라운데라께서 점지한 운명을 거스르진 못해도, 그 짧은 생 찰나의 시간이라도 더 벌어주기 위해 고군분투했었다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111861","time":"2026-06-23T17:32:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"아아, 저 피먹은 황야에서 스러져가는 이들을 보며, 그 시절의 파우스트는 무슨 감정을 품었었나","characters":["P-44a1082366bf"]},{"id":"RP-II-0111862","time":"2026-06-23T17:33:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"무덤께에 바칠 편지 하나 쓰기 이리도 벅차, 잠시 눈을 감고 한숨을 내쉬었다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111863","time":"2026-06-23T17:34:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"지금도 아지랑이처럼 눈 앞을 어지럽히는 잔영들","characters":["P-44a1082366bf"]},{"id":"RP-II-0111864","time":"2026-06-23T17:34:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"한 여인이 있었다.\n하급 기사였으며, 손재주가 부족해 붕대를 엉성하게 감아오던걸 몇번이고 고쳐주던 이였다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111865","time":"2026-06-23T17:37:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"목소리가 제법 고와서 붕대를 감아줄 때면 옆에서 재잘거리는 것을 듣는 재미가 있었다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111866","time":"2026-06-23T17:41:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"오늘 식사가 맛있었다느니, 훈련이 힘들었다느니 가벼운 일상을 말해주었던가","characters":["P-44a1082366bf"]},{"id":"RP-II-0111867","time":"2026-06-23T17:41:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"그런 그녀는 손목 한마디만 남아 돌아왔다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111868","time":"2026-06-23T17:42:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"한 사내가 있었다.\n술을 어찌나 좋아했는지, 등짝을 스무 바늘 이상 꼬맨 날에도 몰래 독한 술을 들여와 마시곤 했다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111869","time":"2026-06-23T17:45:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"몇번이고 타박하고 잔소리를 퍼부어도 고쳐지지 않던 버릇은, 그 머리가 떨어지고 나서야 멈추게 되었다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111870","time":"2026-06-23T17:46:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"막사에서 환자들을 돌보는 잠깐 사이에도 수많은 사고들이 들려온다. 누구의 팔이 잘렸다더라, 누구는 독에 당해 피를 토했다더라, 누구의 목에 화살이 박혔다더라","characters":["P-44a1082366bf"]},{"id":"RP-II-0111871","time":"2026-06-23T17:48:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"새처럼 날개달린 몬스터에게 끌려갔다 추락해 으스러진 이가 있었고, 작열하는 불길 속에서 작게 쪼글아들어버린 이가 있었으며, 부러진 뼈가 폐를 찔러 질식한 이가 있었다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111872","time":"2026-06-23T17:49:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"파우스트는 그런 이들 하나하나 이름을 기억해두었다가, 이따금 묘지에 들릴 때면 편지 한장, 꽃 한송이 올려두곤 했다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111873","time":"2026-06-23T17:51:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"슬퍼할지언정 무너지진 않았다. 이는 어딘가에선 매우 흔한 비극일 수 있었다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111874","time":"2026-06-23T17:51:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"그 시절 우리는 명예롭지 못했으나, 숭고했을 뿐이다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111875","time":"2026-06-23T17:51:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"그러니 파우스트는 놓아둔 만년필을 다시금 들어올리고, 편지지를 한줄 두줄 채워나갔다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111876","time":"2026-06-23T17:53:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"곧 피어날 꽃송이들을 떠올리며 말이다","characters":["P-44a1082366bf"]},{"id":"RP-II-0111877","time":"2026-06-23T17:53:00+09:00","room":"RP II","name":"파우스트","profile":"존","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-44a1082366bf"]},{"id":"RP-II-0111878","time":"2026-06-23T17:53:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
